describe('Textarea Character Count Validation', () => {
  beforeEach(() => {
    cy.visit('/');
    cy.get('textarea').as('textarea');
  });

  it('should display character count and enforce 500 character limit', () => {
    const testText = 'a'.repeat(500);

    cy.get('@textarea').type(testText);
    cy.get('@textarea').should('have.value', testText);
    cy.get('[data-testid="char-count"]').should('contain', '500 / 500');

    cy.get('@textarea').type('extra');
    cy.get('@textarea').should('have.value', testText);
    cy.get('[data-testid="char-count"]').should('contain', '500 / 500');
  });

  it('should update character count in real-time as user types', () => {
    cy.get('@textarea').type('Hello');
    cy.get('[data-testid="char-count"]').should('contain', '5 / 500');

    cy.get('@textarea').type(' World');
    cy.get('[data-testid="char-count"]').should('contain', '11 / 500');

    cy.get('@textarea').clear();
    cy.get('[data-testid="char-count"]').should('contain', '0 / 500');
  });

  it('should handle paste operations and respect character limit', () => {
    const largeText = 'a'.repeat(750);

    cy.get('@textarea').invoke('val', largeText).trigger('input');
    cy.get('@textarea').should('have.value', 'a'.repeat(500));
    cy.get('[data-testid="char-count"]').should('contain', '500 / 500');
  });

  it('should display warning state when approaching limit', () => {
    const almostFullText = 'a'.repeat(450);

    cy.get('@textarea').type(almostFullText);
    cy.get('[data-testid="char-count"]').should('not.have.class', 'warning');

    cy.get('@textarea').type('a'.repeat(40));
    cy.get('[data-testid="char-count"]').should('have.class', 'warning');
  });

  it('should handle special characters and spaces correctly', () => {
    const specialText = '!@#$%^&*() \n\t';

    cy.get('@textarea').type(specialText);
    cy.get('[data-testid="char-count"]').should('contain', `${specialText.length} / 500`);
  });

  it('should maintain character count after form submission attempt', () => {
    const testText = 'Test content';

    cy.get('@textarea').type(testText);
    cy.get('button[type="submit"]').click();
    cy.get('[data-testid="char-count"]').should('contain', `${testText.length} / 500`);
    cy.get('@textarea').should('have.value', testText);
  });
});
